package com.nuvio.app.features.player

import com.nuvio.app.core.storage.DesktopPrefsStorage
import kotlinx.serialization.json.JsonObject

internal actual object PlayerSettingsStorage {
    actual fun loadShowLoadingOverlay(): Boolean? = DesktopPrefsStorage.getBoolean("ps_show_loading_overlay")
    actual fun saveShowLoadingOverlay(enabled: Boolean) = DesktopPrefsStorage.putBoolean("ps_show_loading_overlay", enabled)
    actual fun loadResizeMode(): String? = DesktopPrefsStorage.getString("ps_resize_mode")
    actual fun saveResizeMode(mode: String) = DesktopPrefsStorage.putString("ps_resize_mode", mode)
    actual fun loadHoldToSpeedEnabled(): Boolean? = DesktopPrefsStorage.getBoolean("ps_hold_speed_enabled")
    actual fun saveHoldToSpeedEnabled(enabled: Boolean) = DesktopPrefsStorage.putBoolean("ps_hold_speed_enabled", enabled)
    actual fun loadHoldToSpeedValue(): Float? = DesktopPrefsStorage.getFloat("ps_hold_speed_value")
    actual fun saveHoldToSpeedValue(speed: Float) = DesktopPrefsStorage.putFloat("ps_hold_speed_value", speed)
