    actual fun savePreferredAudioLanguage(language: String) = DesktopPrefsStorage.putString("ps_preferred_audio_lang", language)
    actual fun loadSecondaryPreferredAudioLanguage(): String? = DesktopPrefsStorage.getString("ps_secondary_audio_lang")
    actual fun saveSecondaryPreferredAudioLanguage(language: String?) { if (language != null) DesktopPrefsStorage.putString("ps_secondary_audio_lang", language) else DesktopPrefsStorage.remove("ps_secondary_audio_lang") }
    actual fun loadPreferredSubtitleLanguage(): String? = DesktopPrefsStorage.getString("ps_preferred_sub_lang")
