    actual fun saveSubtitleOutlineEnabled(enabled: Boolean) = DesktopPrefsStorage.putBoolean("ps_sub_outline", enabled)
    actual fun loadSubtitleFontSizeSp(): Int? = DesktopPrefsStorage.getInt("ps_sub_font_size")
