    actual fun saveAnimeSkipClientId(clientId: String) = DesktopPrefsStorage.putString("ps_anime_skip_client_id", clientId)
    actual fun loadIntroDbApiKey(): String? = DesktopPrefsStorage.getString("ps_introdb_api_key")
    actual fun saveIntroDbApiKey(apiKey: String) = DesktopPrefsStorage.putString("ps_introdb_api_key", apiKey)
    actual fun loadIntroSubmitEnabled(): Boolean? = DesktopPrefsStorage.getBoolean("ps_intro_submit")
    actual fun saveIntroSubmitEnabled(enabled: Boolean) = DesktopPrefsStorage.putBoolean("ps_intro_submit", enabled)
    actual fun loadStreamAutoPlayNextEpisodeEnabled(): Boolean? = DesktopPrefsStorage.getBoolean("ps_autoplay_next")
    actual fun saveStreamAutoPlayNextEpisodeEnabled(enabled: Boolean) = DesktopPrefsStorage.putBoolean("ps_autoplay_next", enabled)
